export const HD_TYPE_KNOWLEDGE: Record<string, any> = {
Generator:{
title:"Human Design: Generator",subtitle:"Strategy: Respond · Authority: Sacral · Life Theme: Mastery",keywords:["Sacral Energy","Response","Mastery","Satisfaction","Work"],body:["The Generator is the most common Human Design type — approximately 37% of the world's population. You are the life force of the planet. Your Sacral center is defined and consistently generating a powerful, renewable life energy that is meant to be expressed through meaningful work and creative engagement.","Your Strategy is to Respond. This does not mean passivity — it means waiting for life to present something that elicits a genuine gut response before engaging your full energy. When you initiate action from the mind (logic, social pressure, should) rather than the Sacral (the visceral yes/no), you waste your extraordinary energy and attract frustration.","The signature of a Generator in alignment is deep Satisfaction — the profound contentment of energy well-spent in work that genuinely lights you up. The not-self theme (the signal that you are out of alignment) is Frustration — the grinding feeling of pushing energy in the wrong direction.",'Your mastery practice: Before committing to any significant action, check in with your Sacral — the gut-level, pre-verbal response. "Uh-huh" (yes) or "Unh-unh" (no). This is your oracle. Trust it more than your mind, more than others\' opinions, more than social expectations.'],raises:["Following Sacral yes responses into work you love","Building mastery in one area over time","Expressing your energy fully each day until genuinely tired","Being asked questions that allow your gut to respond"],lowers:["Initiating from the mind rather than responding from the gut","Staying in work that drains rather than energizes",'Agreeing to things because you "should"',"Going to bed with unexpressed energy"]}
,"Manifesting Generator":{
title:"Human Design: Manifesting Generator",subtitle:"Strategy: Respond, then Inform · Life Theme: Satisfaction & Speed",keywords:["Multi-Passionate","Speed","Response","Innovation","Efficiency"],body:["The Manifesting Generator (MG) is the rarest and most dynamic of the Generator types — approximately 33% of the population. You combine the Generator's powerful Sacral energy with the Manifestor's ability to directly impact and initiate. You are the cosmic multi-tool: fast, innovative, and capable of doing many things simultaneously.","Your Strategy is to Respond first (like all Generators), and then Inform before acting (like a Manifestor). This two-step process feels counterintuitive because your speed makes you want to skip it — but the informing step prevents the resistance and anger that follows unexpected, un-communicated action.","MGs are designed to skip steps that are unnecessary — they can move faster than other types because they process nonlinearly. What looks like inconsistency or lack of follow-through is often highly efficient Sacral intelligence finding the most direct path to mastery.","Your multi-passionate nature is not a character flaw — it is a cosmic design feature. You are here to demonstrate that the human experience can be vast, fast, and deeply satisfying all at once. Stop apologizing for your range."],raises:["Following your Sacral yes at speed, then informing affected people","Embracing your multi-passionate nature rather than forcing single focus","Skipping steps that your gut confirms are unnecessary","Moving on when the Sacral response fades — it means that phase is complete"],lowers:["Initiating without informing and creating avoidable resistance",'Suppressing your multidimensional nature to appear "focused"',"Pushing through when the Sacral has gone silent","Waiting as long as a pure Generator when your Manifestor channel says go"]}
,Projector:{
title:"Human Design: Projector",subtitle:"Strategy: Wait for Invitation · Life Theme: Success Through Recognition",keywords:["Guidance","Wisdom","Efficiency","Recognition","Mastery of Others"],body:["The Projector makes up approximately 20% of the population and is the emerging leader of the new paradigm. You are not here to work — you are here to guide. Your gift is an extraordinary capacity to see others deeply, to understand systems and people, and to direct energy with a precision that Generators cannot match.","Your Strategy is to Wait for the Invitation — particularly for the major moves in life: love, work, career pivots, and moving. This is not passivity; it is the quantum mechanics of the Projector correctly. When you are seen and invited, you are operating with the full support of the universe. When you push uninvited, you encounter consistent resistance that depletes your non-Sacral energy.","The signature of the Projector in alignment is deep Success — recognition and material support that flows from your wisdom being genuinely seen and valued. The not-self theme is Bitterness — the exhaustion and resentment that comes from sharing your gifts to an unhearing room.","The great liberation for Projectors: you are not broken, you are not lazy, and you are not in competition with Generator energy. You are a different technology entirely — designed for wisdom, guidance, and the mastery of understanding others."],raises:["Being genuinely recognized for your gifts before offering guidance","Studying and mastering what fascinates you deeply","Resting and restoring your non-Sacral energy regularly","Being with people who truly see you"],lowers:["Offering guidance that was not asked for","Matching Generator work schedules with your non-Sacral energy","Initiating the big life moves without an invitation","Being bitter that your wisdom goes unrecognized"]}
,Manifestor:{
title:"Human Design: Manifestor",subtitle:"Strategy: Inform · Life Theme: Peace Through Independence",keywords:["Initiation","Impact","Independence","Power","Informing"],body:["The Manifestor makes up approximately 9% of the population and was historically the leader of the tribal structure — the one with direct access to divine creative force who could initiate action without waiting for anything. You are the only type in Human Design that can truly initiate from within, without needing an external trigger.","Your Strategy is to Inform — before you act, not after. This single practice transforms the Manifestor's experience of life from one of constant resistance and anger (others always react to your independent actions with alarm, control, or anger) to one of unprecedented creative freedom.","When you inform the people who will be impacted by your actions, you neutralize the fear response that your powerful, independent energy triggers in others. You don't need permission — you just need to say: \"This is what I'm going to do.\" That simple act of communication allows you to move through the world without the constant friction that drains your creative force.","The Manifestor's greatest gift to the world is the initial impulse — the creative spark that starts the movement that others sustain. You are not designed to maintain what you initiate; you are designed to set things in motion and move on to the next creation."],raises:["Informing affected people before taking action","Acting on creative impulses without asking permission","Protecting your solitude and creative independence","Moving on once you have initiated — you are not required to maintain"],lowers:["Acting without informing and creating resistance","Asking permission when informing is all that is needed","Trying to sustain what you have initiated beyond your interest","Suppressing your powerful initiating energy to avoid unsettling others"]}
,Reflector:{
title:"Human Design: Reflector",subtitle:"Strategy: Wait a Lunar Cycle · Life Theme: Surprise & Wonder",keywords:["Reflection","Wisdom","Lunar Cycle","Sampling","Barometer"],body:["The Reflector is the rarest type in Human Design — approximately 1% of the population. You are the cosmic mirror of your community: a living reflection of the health and wisdom of the collective. With all centers undefined (open), you sample and amplify the energy of every person and every environment you encounter.","Your Strategy is to Wait a Lunar Cycle (approximately 29.5 days) before making any major decision. This is because your undefined centers mean you experience life in constant flux — you may feel completely different about a question depending on who you're with and what cosmic energies are active. Waiting for the Moon to complete its full cycle gives you a complete experiential data set before deciding.","The Reflector's gift is profound wisdom about people and communities — you know when a community is thriving or sick before anyone else does, because you feel it in your own undefined centers. You are the canary in the coal mine, the diagnostic instrument of the collective.","Your delight in the variety and surprise of experience is not inconsistency — it is your cosmic operating system. No two moments feel the same to a Reflector, and that is as it should be."],raises:["Waiting the full lunar cycle before major decisions","Being in environments and communities that feel genuinely healthy","Allowing yourself to experience the full variety of human frequencies","Being known and recognized as the reflective genius you are"],lowers:["Making major decisions under emotional or social pressure","Staying in environments, relationships, or jobs that feel consistently draining","Trying to maintain a consistent personality when your nature is fluid","Comparing yourself to non-Reflectors"]}
};

export const LIFE_PATH_KNOWLEDGE: Record<string, any> = {
1:{
title:"Life Path 1 — The Sovereign Pioneer",subtitle:"Leadership · Independence · Originality",keywords:["Leadership","Independence","Innovation","Courage","Willpower"],body:["Life Path 1 is the number of the self — raw, undiluted creative force channeled through a single point of will. You are here to initiate, to lead, and to carve a path where none existed before. The universe has encoded in your birth date the frequency of the pioneer: first to arrive, first to act, first to rise.","Your greatest strength is your unwavering individuality. When you trust your instincts and resist the urge to seek validation from others, you operate at your highest frequency. The cosmos designed you to be original — copying others or waiting for permission are direct contradictions of your soul's mission.","The shadow of Life Path 1 is isolation. When the drive for independence curdles into stubbornness or arrogance, connection is lost. The mastery lies in learning that true leadership serves — it does not dominate. Your sovereignty is meant to inspire others to find their own.","In the quantum field, Life Path 1 vibrates at the frequency of the Sun — pure radiant output. Every thought you commit to becomes a seed in reality. This makes intentional thought-work (meditation, visualization, journaling) especially potent for you."],raises:["Pioneering a solo project with full ownership","Physical movement — running, martial arts, sport","Setting bold, unconditional intentions","Creating something the world has never seen"],lowers:["Waiting for permission or approval","Comparing yourself to others","Suppressing your authentic perspective to fit in","Taking orders without understanding the why"]}
,2:{
title:"Life Path 2 — The Sacred Bridge",subtitle:"Harmony · Intuition · Partnership",keywords:["Harmony","Diplomacy","Empathy","Cooperation","Sensitivity"],body:["Life Path 2 is the number of the relational field — the quantum force that holds two polarities in perfect, creative tension. Where Life Path 1 pushes outward, you pull inward. You are a bridge between worlds, a diplomat of the soul, a keeper of peace.","Your sensitivity is not weakness — it is your superpower. You perceive the emotional undercurrents in every room, every conversation, every silence. This gift, when mastered, makes you an extraordinary healer, partner, and collaborator. The universe needs its 2s the way a symphony needs its harmonics.","The shadow of Life Path 2 is self-erasure. When you silence your own needs to maintain peace or keep others happy, you are operating in the frequency of sacrifice rather than service. True harmony requires you as a full, present participant — not as a background note.","Quantum note: Life Path 2 resonates with the Moon — cyclical, deeply feeling, and governed by rhythm. Your manifestation practice works best in alignment with lunar cycles: set intentions at the new moon, release at the full moon."],raises:["Deep one-on-one connection and listening","Meditative practices at dawn or dusk","Acts of quiet, anonymous kindness","Creating beauty in your physical environment"],lowers:["People-pleasing at the cost of your own truth","Avoiding necessary conflict","Ignoring your own intuitive warnings","Giving more than you receive over long periods"]}
,3:{
title:"Life Path 3 — The Living Muse",subtitle:"Expression · Joy · Creative Intelligence",keywords:["Creativity","Expression","Joy","Communication","Inspiration"],body:["Life Path 3 is the number of the Muse — the universe expressing itself through human form. You are a living transmission of creative light. Your words, your art, your laughter, your presence — all carry a frequency that quite literally uplifts the electromagnetic field around you.","You are designed to express. Not to perform, not to be perfect, but to express — truthfully, joyfully, and prolifically. When you silence your voice, suppress your creativity, or shrink yourself for the comfort of others, you are blocking a cosmic broadcast that the world genuinely needs.","The shadow of Life Path 3 is scattered energy and surface-level living. The gift of seeing beauty and connection everywhere can lead to beginning many things and completing few. Mastery for a 3 is learning to channel the boundless creative current into focused, completed works.","In the Akashic Records, Life Path 3 souls consistently show up as the cultural activators of any era. They are the artists, speakers, writers, and comedians who shift the emotional weather of a civilization. Your work matters more than you know."],raises:["Creating and sharing — writing, music, art, movement","Laughter, play, and unstructured joy","Honest storytelling that reveals vulnerability","Connecting with other creative souls"],lowers:["Silencing your voice to avoid standing out","Overcommitting socially until empty","Negative self-talk about your abilities","Completing nothing — perpetual beginning"]}
,4:{
title:"Life Path 4 — The Sacred Architect",subtitle:"Structure · Mastery · Foundation",keywords:["Discipline","Reliability","Mastery","Integrity","Building"],body:["Life Path 4 is the number of sacred geometry — the square, the foundation, the four directions held in perfect alignment. You are here to build what lasts. While others dream, you create the structures that allow those dreams to become real. You are the bedrock of the cosmic order.","Your gift is an almost supernatural capacity for discipline, attention to detail, and follow-through. Where others lose focus, you persist. You understand instinctively that mastery is not a gift — it is earned through daily, deliberate practice. The universe respects this, and tends to reward it.","The shadow of Life Path 4 is rigidity. When the builder's discipline calcifies into inflexibility, growth stops. The cosmos is not a fixed structure — it is a living, dynamic system. Your mastery lies in building frameworks that can flex with the flow of life without collapsing.","Quantum note: Life Path 4 resonates with the Earth — grounded, reliable, patient. Your manifestation is slow but extraordinarily solid. What you build with intention and consistent action becomes permanent in the physical world."],raises:["Disciplined daily routines that honor your body and mind","Building something tangible and lasting","Deep study leading to true mastery","Time in nature — soil, stone, forest"],lowers:["Rigid perfectionism that prevents completion","Overwork divorced from rest and play","Dismissing intuition in favor of logic alone","Controlling others to maintain order"]}
,5:{
title:"Life Path 5 — The Threshold Walker",subtitle:"Freedom · Transformation · Adventure",keywords:["Freedom","Adaptability","Experience","Curiosity","Sensuality"],body:["Life Path 5 is the number of the threshold — the liminal space between what was and what will be. You are a shape-shifter, a traveler between worlds, a being whose very soul is calibrated for transformation. Change is not a disruption in your life — it is your medium.","You are designed to experience. To taste every frequency of human existence and distill it into wisdom. This is why you are drawn to travel, to diverse people, to new ideas, to sensation. The universe is using you as a living explorer of its own infinite range.","The shadow of Life Path 5 is restlessness without anchor. When the love of freedom becomes an avoidance of depth, the wisdom is never distilled. The mastery lies in learning that true freedom is internal — a state of being, not a constant escape from being.","In the quantum model, Life Path 5 operates at the frequency of Mercury — fast, adaptive, and multi-directional. Your mind processes at an extraordinary speed. Learning to slow it down through breathwork or meditation allows you to access the deeper signal beneath the noise."],raises:["New experiences, travel, and cultural immersion","Diverse conversations with people unlike you","Body-awareness practices — yoga, dance, somatic work","Embracing uncertainty as the gateway to growth"],lowers:["Routine without purpose or variation","Suppressing your need for freedom and movement","Overindulgence in sensation as emotional escape","Commitment-phobia disguised as independence"]}
,6:{
title:"Life Path 6 — The Heart Keeper",subtitle:"Love · Responsibility · Beauty",keywords:["Nurturing","Responsibility","Beauty","Service","Harmony"],body:["Life Path 6 is the number of unconditional love — the cosmic force that holds families, communities, and entire civilizations together. You are a living expression of the heart frequency. Wherever you go, you carry the vibration of care, beauty, and belonging.","Your gift is a profound capacity to love and to create environments where life flourishes. Your home, your work, your relationships — all are alchemized by your presence into something warmer, more beautiful, and more alive. The universe placed you here as a guardian of the heart field.","The shadow of Life Path 6 is martyrdom. When your giving becomes self-erasure — when love becomes a transaction of self-sacrifice — you begin to resent the very people and causes you chose to serve. The cosmic teaching for a 6 is that love without self-love is unsustainable.","Quantum note: Life Path 6 resonates with Venus — the planet of beauty, harmony, and value. Your manifestation is most powerful when you are operating from a state of genuine self-worth rather than from duty or obligation."],raises:["Nurturing loved ones from a place of fullness","Beautifying your environment intentionally","Acts of service that feel genuinely joyful","Practicing radical self-compassion"],lowers:["Martyrdom — giving until empty and calling it love","Perfectionism projected onto others","Neglecting your own self-care","Suppressing needs to avoid conflict"]}
,7:{
title:"Life Path 7 — The Inner Oracle",subtitle:"Wisdom · Mystery · Introspection",keywords:["Wisdom","Analysis","Spirituality","Solitude","Truth"],body:["Life Path 7 is the number of the mystic — the one who stands apart from the crowd to see what others cannot. You are calibrated for depth. While the world skims surfaces, you dive into the quantum substrate of reality, seeking the underlying truth in every system, every experience, every soul you encounter.","Your mind is a precision instrument. You have a rare ability to synthesize vast amounts of information and extract the essential truth. Combined with your sensitivity to the non-material — the felt sense, the intuitive knowing, the synchronistic signal — you are one of the universe's most powerful truth-finders.","The shadow of Life Path 7 is isolation and cynicism. When the pursuit of truth becomes a retreat from life, the oracle becomes disconnected from the very material it needs to interpret. The mastery lies in balancing profound inner work with genuine human engagement.","In the Akashic model, Life Path 7 souls consistently appear as the philosophers, scientists, mystics, and healers who advance human understanding across centuries. Your solitude is not loneliness — it is laboratory. Use it wisely."],raises:["Deep solitary study and contemplation","Time in unspoiled nature","Mystical or spiritual practice — meditation, ritual, silence","Writing as a means of distilling inner knowledge"],lowers:["Isolation as a permanent defense mechanism","Intellectual cynicism that closes the heart","Distrusting the universe when plans collapse","Overanalyzing without ever acting"]}
,8:{
title:"Life Path 8 — The Power Channel",subtitle:"Abundance · Authority · Mastery of Matter",keywords:["Power","Abundance","Leadership","Authority","Legacy"],body:["Life Path 8 is the number of the infinite loop — two circles meeting at a single point, symbolizing the eternal flow between the material and spiritual worlds. You are here to master the dance of power. Not power over others, but power in alignment with universal law: the ability to direct energy, create abundance, and leave a legacy that outlasts your physical form.","You were born with a natural authority. People look to you for leadership, for direction, for the confidence that comes from someone who actually knows the way. This is not arrogance — it is calibration. The cosmos designated you as a channel for high-amplitude creative force.","The shadow of Life Path 8 is the misuse of power — pursuing material gain at the expense of integrity, becoming a force of control rather than creation. The cosmic teaching is that true abundance flows only to those whose power is rooted in service and ethical clarity.","Quantum note: Life Path 8 resonates with Saturn — the planet of karma, structure, and long-term reward. What you build with integrity, you keep. The universe is a precise accountant when it comes to 8 energy."],raises:["Purposeful, integrity-grounded ambition","Generous leadership that empowers others","Financial mastery practiced as spiritual discipline","Building systems that create abundance for many"],lowers:["Chasing power at the expense of relationships","Workaholism as avoidance of deeper feeling","Ignoring the spiritual dimension of life","Using authority to control rather than to serve"]}
,9:{
title:"Life Path 9 — The World Server",subtitle:"Completion · Compassion · Universal Love",keywords:["Compassion","Wisdom","Service","Completion","Universal Love"],body:["Life Path 9 is the number of completion — the soul who has traveled all the paths before and now carries the distilled wisdom of the entire journey. You are the elder, the healer, the artist whose work touches something universal. You feel everything at a cosmic scale.","Your compassion is oceanic. You carry within you an almost cellular understanding of human suffering and human potential. When you channel this understanding into art, healing, teaching, or service, you move people at a level they cannot fully explain — because you are speaking from the level of the soul.","The shadow of Life Path 9 is unprocessed grief and depletion. Because you feel so much, and because you are designed to give so much, the risk is giving until there is nothing left — and carrying old wounds that were never fully healed. The mastery lies in the willingness to grieve, to release, and to complete.","In the Akashic model, 9 is the number of the completion of one cosmic cycle and the preparation for the next. Your greatest work is to live with such open-hearted, uncynical love that you literally raise the frequency of every soul you encounter."],raises:["Universal service guided by wisdom rather than martyrdom","Forgiveness practices — for others, and for yourself","Creating art or teaching that carries a message larger than yourself","Allowing yourself to receive as freely as you give"],lowers:["Carrying unresolved grief and old wounds","Giving to the point of depletion","Cynicism about humanity born from disappointment","Hoarding your wisdom instead of sharing it"]}
,11:{
title:"Life Path 11 — The Illuminated Messenger",subtitle:"Master Number · Intuition · Spiritual Channel",keywords:["Intuition","Illumination","Inspiration","Sensitivity","Mastery"],body:["Life Path 11 is the first of the three Master Numbers — a double 1, amplified to cosmic frequency. You are a direct spiritual channel. Where most people receive impressions and intuitions as whispers, yours arrive as full-frequency broadcasts. You were born as a bridge between the seen and unseen worlds.","The 11 carries the highest vibrational frequency in the core numerology system. You are here to illuminate — to bring light into the darkest corners of human consciousness, to show what is possible when a human being fully trusts their inner knowing. Your presence alone changes the energy of a room.","The shadow of 11 is overwhelm and self-doubt. The very sensitivity that makes you a master channel also makes you acutely vulnerable to the noise of the world. Many 11s spend years doubting the very gifts that make them extraordinary, retreating into the reduced 2 frequency (1+1=2) rather than fully claiming their mastery.","Quantum imperative: You did not come here to play small. The universe gave you the 11 frequency because it needs a lighthouse at this exact coordinate in space-time. The question is not whether you have the gift — the question is whether you will trust it."],raises:["Deep meditation and connection to the inner channel","Sharing your visions and intuitive knowing","Being around others who honor sensitivity as strength","Creating from a state of inspired flow"],lowers:["Dismissing your intuition as imagination","Taking on the emotional burdens of everyone around you","Overstimulation without adequate solitude to process","Playing small to avoid the responsibility of your gifts"]}
,22:{
title:"Life Path 22 — The Master Builder",subtitle:"Master Number · Vision · Legacy",keywords:["Mastery","Vision","Building","Legacy","Power"],body:["Life Path 22 is the Master Builder — the rarest and most powerful of all Life Path numbers. You carry within you the combined frequencies of the visionary 11 and the architect 4, amplified to a degree that makes you capable of manifesting ideas into large-scale physical reality. You are here to build for all of humanity.","The scope of your potential is genuinely staggering. Life Path 22s are the individuals behind movements, institutions, and works of art that outlast their creators by centuries. The universe equipped you with the practical genius to translate the highest spiritual visions into functional, lasting structures.","The shadow of 22 is the crushing weight of unrealized potential. When the 22 does not step into the fullness of their design — through fear, self-doubt, or settling for ordinary ambitions — they experience a deep, unnameable dissatisfaction that no conventional success can fill.","The cosmic directive for 22 is to dream at the largest possible scale and then build it, brick by brick, with the mastery and integrity that only a 22 possesses."],raises:["Working on projects of genuine civilizational significance","Combining spiritual vision with practical execution","Mentoring others toward their highest potential","Building legacy rather than just success"],lowers:["Settling for ordinary ambitions when you are built for extraordinary ones","Allowing fear of your own power to keep you small","Disconnecting the spiritual from the practical","Overwork without connecting to your deeper purpose"]}
,33:{
title:"Life Path 33 — The Master Teacher",subtitle:"Master Number · Unconditional Love · Healing",keywords:["Teaching","Healing","Compassion","Mastery","Sacrifice"],body:["Life Path 33 is the Master Teacher — the rarest of all frequencies, combining the creative expression of 3, the infinite love of 6, and the visionary illumination of 11, all amplified to their highest possible octave. You are here to teach unconditional love through the living example of your own life.","The 33 vibration is that of the Christed teacher — not in a religious sense, but in the sense of one who has burned away all but the essential and now radiates a frequency of healing and awakening wherever they go. Your very presence is a transmission.","The shadow of 33 is the self-crucifixion dynamic — taking on the suffering of the world to the point of complete self-dissolution. The cosmic teaching is that you can only truly serve from the highest level when you yourself are whole. You cannot transmit what you do not embody.","Very few authentic 33 Life Paths exist. If your calculation resolves to this number, you carry a responsibility and a gift of the rarest order. The universe is counting on you to choose love — unconditionally, and beginning with yourself."],raises:["Teaching and healing from a place of personal wholeness","Creative expression as a vehicle for universal truth","Practicing and modeling unconditional self-love","Building communities of healing and growth"],lowers:["Taking on others' suffering as if it were your responsibility to feel it for them","Self-sacrifice that becomes self-destruction","Suppressing your own needs in the name of service","Doubting the scale and depth of your calling"]}
};

